+    context = null;
+    await expect(
+      test.slot.handleRequest('ios-simulator', { kind: 'status' }),
+    ).resolves.toMatchObject({ ok: false, errorCode: 'HOST_NOT_READY' });
+    expect(authorizeFocusedContext).toHaveBeenCalledTimes(1);
+  });
