+function stripShellControlTokens(tokens: string[]): string[] {
+  const out = [...tokens];
+  while (out.length > 0 && /^(?:\{|\(|!|then|do|else|elif|if|while|until)$/.test(out[0]!)) {
+    out.shift();
+  }
